import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>PNG 是标志、图标和截图的常用格式，但它也很占体积。一张 PNG 头图可能有好几 MB，同样一张图转成 WebP，体积只有原来的零头。</p>\n<p>PNG 转 WebP 能保留让 PNG 好用的透明度，同时把文件大幅缩小。一次转换，两个格式的优点都占了。</p>\n<p>这篇指南会讲清楚转换是怎么进行的，该用什么设置，以及你的 PNG 文件什么时候适合转成 WebP。</p>\n<h2 id=\"what-is-png-to-webp\">什么是 PNG 转 WebP？</h2>\n<p>PNG 转 WebP 是读取一个 PNG 文件，再把它重写为 WebP。像素保持不变，包括透明区域在内，只是存储方式变得高效得多。</p>\n<p>WebP 同时支持有损压缩和无损压缩。转换器默认用有损 WebP，文件能缩得很小，看起来依然干净。</p>\n<p>透明度在转换中得以保留。透明标志还是透明的，柔和的阴影依然渐渐淡出，这是转 JPG 永远做不到的关键优势。</p>\n<p>结果就是一个能在现代网站上使用、加载更快、看起来和原来 PNG 一模一样的文件。</p>\n<h2 id=\"how-much-smaller\">WebP 比 PNG 小多少？</h2>\n<p>存成 PNG 的照片，转 WebP 通常能小 60% 到 80%。一张 5MB 的 PNG 照片，用 85% 画质转完只剩 1MB 到 2MB。</p>\n<p>标志和图标省得少一些，但依然实实在在，常常是 25% 到 50%。简单图形用 PNG 本来就压得不错，WebP 能再省的空间就有限了。</p>\n<p>带文字的截图能省 50% 到 70%，文字还保持清晰可读。这个组合让它成为博客图片和文档配图的理想选择。</p>\n<p>无损 WebP 比有损 WebP 省得少，但仍比 PNG 小 20% 到 30%。每个像素都必须完美时，无损 WebP 是最小的精确副本。</p>\n<h2 id=\"transparency-preserved\">透明度得以保留</h2>\n<p>WebP 和 PNG 一样存有透明通道。透明区域保持透明，半透明像素的透明程度也分毫不差。</p>\n<p>柔和的阴影在转换中得以保留。从实色渐渐淡到看不见的投影，在 WebP 里依然平滑过渡，JPG 永远做不到这一点。</p>\n<p>下载前用对比查看器检查一下结果。放大看标志边缘，确认透明度干净，没有光晕和毛边。</p>\n<p>要在很多种背景上使用的标志，WebP 是最好的网页格式。它比 PNG 更小，又保留了透明度，所有现代浏览器都能显示。</p>\n<h2 id=\"quality-settings\">实用的画质设置</h2>\n<p>透明 PNG 标志用 85% 到 90% 画质最合适。标志保持锐利，边缘干净，文件却比 PNG 小得多。</p>\n<p>带文字的 PNG 截图用 85%，字保持可读，文件大幅缩小。画质再低，小字会变软，写文档时要避免。</p>\n<p>存成 PNG 的照片用 80% 到 85% 最合适。照片看起来干净，文件只有 PNG 的零头。</p>\n<p>网站头图用 80%，大小和画质平衡得很好。图片铺满屏幕，文件又小到能快速加载。</p>\n<h2 id=\"icon-sets\">整套图标一起转换</h2>\n<p>五十张 PNG 图标可以一次批量转成 WebP。每个文件独立转换，最后打包进一个 ZIP，直接就能上传。</p>\n<p>整套用同一个画质设置。图标常常一起出现，画质不一致看起来会参差不齐。</p>\n<p>转换后抽查两三张图标就行，不用五十张全看。设置相同，抽查的几张没问题，其余的也不会有问题。</p>\n<p>单个文件最大支持 25MB，再大的图标文件和高清产品渲染图都不用提前处理，直接就能转。</p>\n<h2 id=\"screenshots-with-text\">带文字的截图</h2>\n<p>同样文件大小下，WebP 保留文字的效果比 JPG 好。截图用 85% 画质转成 WebP，字保持可读，JPG 版却会变软。</p>\n<p>这让 WebP 成为博客截图、文档图片和教程配图的更好选择，因为这些图片里的文字本身就是内容。</p>\n<p>每个字都必须完美的截图，比如法律证据，那就考虑无损 WebP 或 PNG。有损 WebP 很好，但还不够完美。</p>\n<p>下载前用对比查看器检查最小的文字。放大看菜单和正文，确认读起来干净清晰。</p>\n<h2 id=\"hero-images\">网站头图</h2>\n<p>头图是网页顶部的大横幅，往往是整个网站最重的图片。把它从 PNG 转成 WebP，页面体积能大幅下降。</p>\n<p>头图用 WebP 比 PNG 好，因为同样画质下它更小。一张 4MB 的 PNG 头图变成 1MB 的 WebP，页面加载能快好几秒。</p>\n<p>头图带透明叠加层或抠出来的产品时，WebP 也比 JPG 好。JPG 给不了透明通道，WebP 可以。</p>\n<p>头图没有透明部分时，WebP 和 JPG 都行。WebP 更小，JPG 更兼容，按你的受众来选。</p>\n<h2 id=\"metadata-and-colour\">元数据与色彩配置</h2>\n<p>PNG 转 WebP 会去掉 PNG 的文本块，比如制作软件备注和注释。画布只重画像素，元数据不会跟着过来。</p>\n<p>这对隐私是好事。分享出去的 WebP 不带制作软件或来源机器的记录。</p>\n<p>色彩配置是个微妙的点。转换器可能无法完全保留 PNG 的色彩配置，饱和度高的颜色用之前要和原图对照一下。</p>\n<p>大多数网页图片的颜色变化肉眼看不出来。产品照片这种对颜色敏感的工作，要把 WebP 和 PNG 仔细对比一下。</p>\n<h2 id=\"when-webp-is-larger\">WebP 反而更大的时候</h2>\n<p>偶尔转出来的 WebP 会比原 PNG 大。图片特别简单时就会这样，PNG 对纯色区域的压缩本来就很高效。</p>\n<p>只有两种颜色的小图标，转成 WebP 可能还会变大一点，因为格式本身的头部信息是 PNG 不需要的额外开销。</p>\n<p>WebP 更大时就留着 PNG。没人规定 WebP 必须永远赢，目标是文件更小，而不是某个特定格式。</p>\n<p>每张卡片上都显示转换前后的大小。两个数字一对照，决定一目了然。</p>\n<h2 id=\"png-vs-jpg-decision\">PNG 转 WebP 还是转 JPG？</h2>\n<p>图片带透明度，或者要放在网站上时，选 WebP。WebP 保留透明通道，同样画质下文件比 JPG 更小。</p>\n<p>目的地有明确要求时，选 JPG。表单、打印机和老软件常常只写 JPG，会直接拒绝 WebP。</p>\n<p>要放到网上的截图，选 WebP。文字比 JPG 更锐利，文件更小，页面加载也更快。</p>\n<p>要发给表单或邮件的截图，选 JPG。那里兼容性比体积重要，JPG 到处都能打开。</p>\n<h2 id=\"checking-quality\">下载前检查画质</h2>\n<p>点任意卡片上的“对比”，就能并排看到 PNG 和 WebP。拖动分隔线，检查透明度、文字和边缘。</p>\n<p>先检查透明区域。标志边缘出现光晕或毛边，说明画质太低，提高 5 个点通常就能修好。</p>\n<p>第一次转换后不用重新上传就能改画质。原 PNG 还留在队列里，换个设置再对比一次就行。</p>\n<p>批量转换时，抽查三四张有代表性的文件就行，不用每张都看。设置相同，抽查的几张没问题，其余的也不会有问题。</p>\n<h2 id=\"common-mistakes\">常见错误要避开</h2>\n<p>最常见的错误，是标志用了太低的画质。透明边缘最先遭殃，任何标志都要保持 85% 以上的画质。</p>\n<p>另一个错误是转换本来就很小的图标。一张 10KB 的 PNG 图标转了也省不下什么，转出来的 WebP 反而可能更大。</p>\n<p>还有人忘了检查色彩配置。饱和度高的产品照片转换时颜色可能轻微偏移，快速对比一下就能在上线前发现。</p>\n<p>最后，别把 PNG 转成 WebP 再转回 PNG，指望省空间。这样来回一趟只会叠加有损损伤，结果比原文件更差。</p>\n<h2 id=\"webp-for-website-logos\">网站标志用 WebP</h2>\n<p>网站标志用 WebP 比用 PNG 加载更快，透明度还保留着。单个标志省得不多，但一个网站上图标和标志多了，累积起来就很可观。</p>\n<p>标志用 90% 画质转成 WebP。边缘保持锐利，透明度得以保留，文件比 PNG 小四分之一到一半。</p>\n<p>转换后在浅色和深色背景上都检查一下标志。在白色上看着完美的标志，画质太低时在黑色上可能出现淡淡的毛边。</p>\n<p>留着 PNG 原件给老浏览器做备用。picture 元素给现代浏览器提供 WebP，给其他浏览器提供 PNG，每个访客都能看到标志。</p>\n<p>每页都出现的标志，速度上的节省最重要。页眉标志每次页面浏览都要加载，文件小一点，每次访问都快一点。</p>\n<h2 id=\"webp-for-app-icons\">应用图标用 WebP</h2>\n<p>应用图标出现在很多尺寸下，从小小的网站图标到大大的商店列表图都有。WebP 在各种尺寸下都保持锐利，占用存储还比 PNG 少。</p>\n<p>整套图标用 90% 画质转成 WebP。透明度得以保留，边缘保持干净，文件比 PNG 原件小。</p>\n<p>发布前在浅色和深色背景上都测试一下图标。依赖白色背景的图标在深色主题下会直接消失，解决办法是用透明版本。</p>\n<p>上架应用商店前，先查平台的格式规则。有的商店接受 WebP，有的只认 PNG，格式必须符合商店的要求。</p>\n<p>转换后把 PNG 母版留在项目文件夹里。万一哪个商店或平台拒绝 WebP，PNG 马上就能用，不用重新转换。</p>\n<h2 id=\"webp-for-blog-images\">博客图片用 WebP</h2>\n<p>博客图片是 WebP 的经典用途。一篇博客里有十张照片，转成 WebP 后加载快得多，读者在加载快的页面上停留得更久。</p>\n<p>博客里的 PNG 照片用 80% 画质转成 WebP。图片看起来一模一样，文件缩小了三分之二，页面明显变快。</p>\n<p>博客里带文字的截图用 85% 画质 WebP，字保持可读。同样大小下文字比 JPG 更锐利，教程图片尤其需要这一点。</p>\n<p>转换后更新图片引用，再测试一下文章。引用坏了比加载慢更糟，所以页面上的每张图片都要检查。</p>\n<p>把 PNG 原件留在媒体库里做备用。读者的浏览器显示不了 WebP 时，会加载 PNG 版本，谁都不会看到破损图片。</p>\n<h2 id=\"webp-for-ecommerce\">电商图片用 WebP</h2>\n<p>网店的命脉就是图片。几百张产品照片，每张转成 WebP 都小得多，快慢之差就体现在这里。</p>\n<p>产品照片用 80% 到 85% 画质转成 WebP。顾客会放大看产品，多留一点画质能保住他们要检查的细腻质感。</p>\n<p>产品缩略图用 75% 画质就够了。缩略图很小，变软也看不出来，分类页面能瞬间加载。</p>\n<p>转换后在手机上测试一下店铺。现在手机购物者是多数，慢速网络下加载快的店铺，转化率远高于加载慢的。</p>\n<p>转换前后都测一下店铺速度。加载时间实实在在地改善了，团队才看得到转换工作的价值。</p>\n<h2 id=\"webp-for-social-graphics\">社交媒体配图用 WebP</h2>\n<p>社交媒体配图常常带有文字，同样文件大小下 WebP 保留的文字比 JPG 更锐利。公告图用 WebP，平台压缩后读起来依然干净。</p>\n<p>上传前把配图用 85% 画质转成 WebP。平台反正要压缩一次，高质量的输入比低质量的输入结果更好。</p>\n<p>转换前先查平台推荐的尺寸。Instagram、Facebook 和 X 各有理想尺寸，尺寸合适比格式更重要。</p>\n<p>带透明度的配图，比如贴纸或叠加层，只有 WebP 能保留透明。JPG 存不了透明，配图会多出一个纯色背景。</p>\n<p>上传后下载平台上的版本检查一下。快速看一眼发布后的帖子，就能确认图片在平台处理后是否完好。</p>\n<p>准备好把 PNG 变小了吗？打开 <a href=\"/zh/png-zhuan-webp/\">PNG 转 WebP 工具</a>，把文件拖进去就行。具体步骤可以看<a href=\"/zh/blog/ruhe-jiang-png-zhuan-huan-wei-webp/\">如何把 PNG 转换成 WebP</a>，正面对照可以看<a href=\"/zh/blog/png-vs-webp-duibi/\">PNG vs WebP：透明度与文件大小对比</a>。如果目的地要求 JPG，<a href=\"/zh/png-zhuan-jpg/\">PNG 转 JPG 工具</a>就是对应的工具。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"PNG 转 WebP 真的能保留透明背景吗？","answer":"可以。WebP 和 PNG 一样存有透明通道，透明区域保持透明，柔和的阴影也能渐渐淡出。下载前用对比查看器检查一下，放大看标志边缘，确认没有光晕或毛边。"},{"question":"同一张图片，WebP 比 PNG 小多少？","answer":"存成 PNG 的照片，转 WebP 通常能小 60% 到 80%。标志和图标能小 25% 到 50%，因为简单图形用 PNG 本来就压得不错。截图通常能小 50% 到 70%，文字还保持可读。"},{"question":"透明 PNG 标志用什么画质设置最好？","answer":"85% 到 90% 最适合标志，因为画质低了透明边缘最先遭殃。标志保持锐利，边缘干净，文件还比 PNG 小得多。只有头图这种更看重加载速度的大图，才降到 80%。"},{"question":"能一次把整套图标从 PNG 转成 WebP 吗？","answer":"可以。把整套图标拖进转换器，选一个画质设置，再把装着所有 WebP 的 ZIP 下载下来就行。整套用同一个设置，图标放在一起才一致。转换后抽查两三张图标，不用五十张全看。"},{"question":"网站头图用 WebP 比 PNG 好吗？","answer":"通常是的。头图从 PNG 转成 WebP，常常只有原来三分之一大小，肉眼看不出差别，页面加载却快得多。头图带抠图或叠加层时，WebP 还能保留透明度。只有目的地有明确要求时，才留着 PNG。"},{"question":"为什么转出来的 WebP 比原 PNG 还大？","answer":"图片特别简单时就会这样，比如只有两种颜色的小图标，PNG 对纯色区域的压缩本来就很高效。WebP 的头部信息是 PNG 不需要的额外开销。WebP 更大时，就留着 PNG。"}];
